const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(-105.503, 35.759); // Longitude, Latitude
    const geometry = point.buffer(10000); // 10 km buffer around the point
    const scale = 30; // Landsat spatial resolution in meters

    // Define date ranges, expanding slightly to find available imagery
    const date1_start = '2022-04-18'; // +/- 1 day for April 19
    const date1_end = '2022-04-20';
    const date2_start = '2022-04-22'; // +/- 1 day for April 23
    const date2_end = '2022-04-24';

    // 2. Data Acquisition & Pre-processing Function
    function maskL9sr(image) {
      // Bits 2, 3, 4, 5 are cloud shadow, cloud, snow, and water respectively.
      var qa = image.select('QA_PIXEL');
      var cloudShadowBitMask = (1 << 3);
      var cloudsBitMask = (1 << 5);
      // Both flags should be set to zero, indicating clear conditions.
      var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return image.updateMask(mask).select(['SR_B5', 'SR_B7'])
                  .copyProperties(image, ['system:time_start']);
    }

    function calculateNBR(image) {
      return image.normalizedDifference(['SR_B5', 'SR_B7']).rename('NBR')
                  .copyProperties(image, ['system:time_start']);
    }

    // Get Landsat 9 Surface Reflectance collection
    const collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(geometry);

    // Filter for the first date period
    let col1 = collection.filterDate(date1_start, date1_end)
                         .map(maskL9sr)
                         .map(calculateNBR);

    if (col1.size().getInfo() === 0) {
      console.log(`No images found for the first period (${date1_start} - ${date1_end}).`);
      console.log("C1");
      return;
    }
    // Take the closest image for the first period
    const img1 = col1.first();
    const date1 = new Date(img1.get('system:time_start').getInfo()).toISOString().slice(0, 10);
    const nbr1 = img1.select('NBR');

    // Filter for the second date period
    let col2 = collection.filterDate(date2_start, date2_end)
                         .map(maskL9sr)
                         .map(calculateNBR);

    if (col2.size().getInfo() === 0) {
      console.log(`No images found for the second period (${date2_start} - ${date2_end}).`);
      console.log("C1");
      return;
    }
    // Take the closest image for the second period
    const img2 = col2.first();
    const date2 = new Date(img2.get('system:time_start').getInfo()).toISOString().slice(0, 10);
    const nbr2 = img2.select('NBR');

    // 3. Processing: Burn Scar Detection (using NBR threshold)
    // A common threshold for burn scars (severely burned) is NBR < 0.1 or NBR < 0.0.
    // Let's use NBR < 0.0 for severe burns or NBR < 0.1 for general burn scar.
    // For comparing a very recent fire, negative NBR values are strong indicators.
    // We'll use NBR < 0.1 to be inclusive of moderately burned areas.
    const burnThreshold = 0.1;

    const burn1 = nbr1.lt(burnThreshold); // Pixels with NBR less than threshold
    const burn2 = nbr2.lt(burnThreshold);

    // Calculate the area for each burn scar
    // Area of one pixel (square meters)
    const pixelArea = ee.Number(scale).pow(2);

    // Calculate sum of burn pixels
    const burnPixels1 = burn1.rename('burn').reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    });
    const burnPixels2 = burn2.rename('burn').reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    });

    const count1 = ee.Number(burnPixels1.get('burn')).getInfo();
    const count2 = ee.Number(burnPixels2.get('burn')).getInfo();

    if (count1 === null || count2 === null) {
      console.log("C3"); // Calculation failure, likely due to no valid pixels
      return;
    }

    if (count1 === 0 && count2 === 0) {
      console.log("No valid burn scar pixels found for either period after masking.");
      console.log("C2");
      return;
    }

    const area1_sqkm = count1 * pixelArea.getInfo() / 1e6; // Convert to square kilometers
    const area2_sqkm = count2 * pixelArea.getInfo() / 1e6;

    // 4. Validation & Final Answer
    console.log(`Burn scar area on ${date1}: ${area1_sqkm.toFixed(2)} sq km (Pixels: ${count1})`);
    console.log(`Burn scar area on ${date2}: ${area2_sqkm.toFixed(2)} sq km (Pixels: ${count2})`);

    if (area2_sqkm > area1_sqkm) {
      console.log("A"); // Yes, burn scar area increased
    } else {
      console.log("B"); // No, burn scar area did not increase
    }

  } catch (error) {
    console.log("D"); // General error (e.g., incorrect band name, syntax error)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
